function Badge({value}:{value:string}){const color=['APPROVED','CONFIRMED','COMPLETED','ACTIVE','PUBLISHED','ACCEPTED','SUBMITTED'].includes(value)?'green':['PENDING','PLANNED','OPEN'].includes(value)?'orange':['REJECTED','DISABLED','DISPUTED'].includes(value)?'red':['IN_PROGRESS','SHORTLISTED'].includes(value)?'blue':'';return <span className={'chip '+color}>{value.toLowerCase().replaceAll('_',' ').replace(/^./,x=>x.toUpperCase())}</span>;}
async function authSubmit(provider:string,values:Record<string,string>){const csrf=await fetch('/api/auth/csrf',{cache:'no-store'}).then(r=>r.json()) as {csrfToken?:string;error?:string};if(!csrf.csrfToken)throw new Error(csrf.error??'Sign-in is not available.');const response=await fetch('/api/auth/'+provider,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-Auth-Return-Redirect':'1'},body:new URLSearchParams({...values,csrfToken:csrf.csrfToken,callbackUrl:location.origin+'/'})});const result=await response.json() as {url?:string;error?:string};if(!response.ok||result.error||result.url?.includes('error='))throw new Error('Unable to sign in. Check your username and password, or try again shortly.');return result;}
function Login({demo,configured}:{demo:boolean;configured:boolean}){
 const [showPassword,setShowPassword]=useState(false),[busy,setBusy]=useState(''),[error,setError]=useState('');const {register,handleSubmit}=useForm<{username:string;password:string}>();
 async function signin(values:Record<string,string>,key:string){setBusy(key);setError('');try{await authSubmit('callback/credentials',values);location.assign(location.origin);}catch(e){setError(e instanceof Error?e.message:'Sign-in failed.');setBusy('');}}
 return <main className="login"><section className="login-brand"><Brand/><div className="login-story"><span className="eyebrow muted">BLUE &amp; GOLD · LEARNING IN MOTION</span><h1>Forged by learning.<br/>Built through experience.<br/><em>Ready for what comes next.</em></h1><p>A blue-and-gold space for your training journey — from your first day to your next opportunity.</p><div className="login-visual" aria-label="Illustrative fictional training summary"><div className="login-visual-head"><div style={{display:'flex',gap:11,alignItems:'center'}}><span className="avatar">JR</span><div><b className="small" style={{color:'#143e7e'}}>Jamie’s training journey</b><p style={{fontSize:12,color:'#4f6b8f'}}>BS Information Technology</p></div></div><span className="chip green"><Check size={11}/>On track</span></div><div className="progress-wrap"><div className="progress-label"><span style={{color:'#466284'}}>Every hour is a step forward</span><b style={{color:'#143e7e'}}>160 / 480 hrs</b></div><div className="progress-line"><span style={{width:'33.3%'}}/></div></div><div className="mini-stats"><div><strong style={{color:'#143e7e'}}>20</strong><span style={{color:'#506a8c'}}>Days of learning</span></div><div><strong style={{color:'#143e7e'}}>1</strong><span style={{color:'#506a8c'}}>Connected team</span></div><div><strong style={{color:'#143e7e'}}>∞</strong><span style={{color:'#506a8c'}}>Possibilities</span></div></div><p style={{fontSize:11,color:'#5a789c',marginTop:14}}>Fictional demo illustration</p></div></div><div className="login-footer"><ShieldCheck size={15}/>RTU-inspired design · Fictional demo data.</div></section><section className="login-main"><div className="login-content"><span className="chip green"><GraduationCap size={13}/>RTU-INSPIRED PRACTICUM PORTAL</span><h2>Welcome to PractiSync</h2><p>Sign in to pick up where your training left off.</p>{error&&<div className="alert" role="alert" style={{marginBottom:15}}>{error}</div>}{!configured&&<div className="alert" style={{marginBottom:15}}>Sign-in is not configured yet. Please contact the app administrator.</div>}<form className="signin-form" onSubmit={handleSubmit(v=>signin(v,'credentials'))}><div className="field"><label htmlFor="username">Username</label><input id="username" placeholder="Enter your university username" autoComplete="username" required {...register('username')}/></div><div className="field"><label htmlFor="password">Password</label><div className="password-wrap"><input id="password" type={showPassword?'text':'password'} placeholder="Enter your password" autoComplete="current-password" required {...register('password')}/><button type="button" aria-label={showPassword?'Hide password':'Show password'} onClick={()=>setShowPassword(!showPassword)}>{showPassword?<EyeOff size={18}/>:<Eye size={18}/>}</button></div></div><button className="primary" disabled={!!busy||!configured}>{busy==='credentials'?<LoaderCircle size={16} className="spin"/>:<LockKeyhole size={15}/>}Sign in</button></form><div className="or">or use your university email</div><button disabled className="secondary google"><span className="google-letter">G</span>Continue with Google</button><p className="login-note">Google sign-in is not configured for this demo.</p>{demo&&<><div className="demo-header"><strong>Take a look around</strong><span className="chip orange">DEMO ACCESS</span></div><p style={{fontSize:12.5,color:'#546f8f',marginBottom:12}}>Choose a role to explore with fictional sample data.</p><div className="demo-grid">{demoAccounts.map((account,i)=>{const Icon=[GraduationCap,BookOpen,ShieldCheck][i];return <button key={account.id} className="demo-account" disabled={!!busy||!configured} onClick={()=>signin({demoId:account.id},account.id)}><span className={'role-icon '+['','blue','purple'][i]}>{busy===account.id?<LoaderCircle size={17} className="spin"/>:<Icon size={17}/>}</span><div><b>{account.title}</b><p>{['Your hours & training','Your classes & students','Your university & accounts'][i]}</p></div></button>;})}</div><p className="login-bottom">Demo accounts are shared. Please use fictional information only.</p></>}<p className="login-bottom">Need an account? Contact your university administrator.</p></div></section></main>;
}
type Field={name:string;label:string;type?:string;options?:{value:string;label:string}[];required?:boolean;hint?:string};
type Modal={action:Action;title:string;description:string;fields:Field[];initial:FormValues;context:Record<string,string>;sample?:boolean;submitLabel?:string};
