 function openDtr(entry?:Row){open('dtr',entry?'Correct attendance':'Log your attendance',[{name:'date',label:'Entry date',type:'date'},{name:'startsAt',label:'Time in · Philippine time',type:'time'},{name:'endsAt',label:'Time out · Philippine time',type:'time',hint:'If earlier than time in, this means the next day.'},{name:'breakMinutes',label:'Break duration (minutes)',type:'number'},{name:'narrative',label:'What did you learn or accomplish?',type:'textarea'},...(entry?[{name:'reason',label:'Reason for correction',type:'textarea'}]:[])],entry?{placementId:s(entry,'placementId'),entryId:entry.id,version:String(entry.version),date:s(entry,'date'),startsAt:localDateTime(s(entry,'startsAt')).slice(11),endsAt:localDateTime(s(entry,'endsAt')).slice(11),breakMinutes:String(entry.breakMinutes),narrative:s(entry,'narrative')}:{placementId:ownPlacement?.id??'',breakMinutes:'0'}, {},true,'Submitted hours count as reported time. Coordinator confirmation is recorded upon review.',entry?'Save correction':'Submit attendance');}
 function openClass(){open('class','Create a class',[{name:'name',label:'Class name'},{name:'section',label:'Block / section'},{name:'courseId',label:'Course',options:courses}],{courseId:courses[0]?.value??''},{},true,'Each class receives its own enrollment code.','Create class');}
